package ro.leo.visual;
import android.app.*;import android.content.*;import android.graphics.*;import android.media.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
/** Native settings checks; restore changed values and never start recording or radio operations. */
public final class SettingsTests extends Instrumentation {
    private void check(boolean v,String message){if(!v)throw new AssertionError(message);}
    private Object field(Object o,String name)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
    private void invoke(final Object target,String name,Class<?>[] types,final Object...args)throws Exception{final java.lang.reflect.Method m=target.getClass().getDeclaredMethod(name,types);m.setAccessible(true);runOnMainSync(new Runnable(){public void run(){try{m.invoke(target,args);}catch(Exception e){throw new RuntimeException(e);}}});waitForIdleSync();}
    private Activity open(Class<?> type){Activity a=startActivitySync(new Intent(getTargetContext(),type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();return a;}
    private void close(final Activity a){if(a!=null)runOnMainSync(new Runnable(){public void run(){a.finish();}});}
    private void capture(String name)throws Exception{SystemClock.sleep(120);Bitmap image=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES).takeScreenshot();check(image!=null,"capture");try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"settings-"+name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}}
    public void onCreate(Bundle args){start();}
    public void onStart(){Context c=getTargetContext();Bundle result=new Bundle();Activity a=null;String mode=Settings.Secure.getString(c.getContentResolver(),InputSettingsActivity.MODE),delay=Settings.Secure.getString(c.getContentResolver(),InputSettingsActivity.DELAY),brightness=Settings.System.getString(c.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS),automatic=Settings.System.getString(c.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS_MODE),timeout=Settings.System.getString(c.getContentResolver(),Settings.System.SCREEN_OFF_TIMEOUT);Map<String,?> ui=c.getSharedPreferences("settings-ui",0).getAll();ArrayList<String> passed=new ArrayList<String>();try{
        a=open(SettingsActivity.class);invoke(a,"switchCategory",new Class<?>[]{int.class},0);check(SettingsActivity.TABS.length==6,"six categories");for(int i=1;i<=6;i++){sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_RIGHT);check((Integer)field(a,"category")==i%6,"category navigation and wrap");}sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_DOWN);int row=((int[])field(a,"selections"))[0];sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_RIGHT);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_LEFT);check(((int[])field(a,"selections"))[0]==row,"per-category selection retained");capture("categories");close(a);a=null;passed.add("six categories, wrap and remembered selection");
        a=open(DisplaySettingsActivity.class);invoke(a,"setBrightness",new Class<?>[]{int.class},128);check(Settings.System.getInt(c.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS)==128,"actual brightness");invoke(a,"setTimeout",new Class<?>[]{int.class},120000);check(Settings.System.getInt(c.getContentResolver(),Settings.System.SCREEN_OFF_TIMEOUT)==120000,"actual timeout");invoke(a,"show",new Class<?>[]{});capture("display");close(a);a=null;passed.add("brightness and screen timeout saved");String raw=(String)Class.forName("android.os.SystemProperties").getMethod("get",String.class,String.class).invoke(null,"persist.leo.keylight.level","");check(raw.isEmpty()||raw.matches("[0-9]{1,3}"),"bounded original keylight property");try{check(DisplaySettingsActivity.setKeylight(8),"Leo UID writes keylight property through restricted root helper");}finally{java.lang.Process restore=new ProcessBuilder("/system/bin/leo-su","-c","setprop persist.leo.keylight.level "+(raw.isEmpty()?"''":Integer.toString(Integer.parseInt(raw)))).start();check(restore.waitFor(3,java.util.concurrent.TimeUnit.SECONDS)&&restore.exitValue()==0,"keylight restored");}passed.add("keylight property and restore");
        a=open(InputSettingsActivity.class);invoke(a,"setMode",new Class<?>[]{int.class},1);invoke(a,"setDelay",new Class<?>[]{int.class},500);check(Settings.Secure.getInt(c.getContentResolver(),InputSettingsActivity.MODE)==1&&Settings.Secure.getInt(c.getContentResolver(),InputSettingsActivity.DELAY)==500,"IME shared settings");invoke(a,"show",new Class<?>[]{});capture("input");close(a);a=null;passed.add("IME settings saved");
        a=open(SoundSettingsActivity.class);for(int type:new int[]{RingtoneManager.TYPE_RINGTONE,RingtoneManager.TYPE_NOTIFICATION,RingtoneManager.TYPE_ALARM}){invoke(a,"tones",new Class<?>[]{int.class},type);ListView tones=null;for(int poll=0;poll<40&&tones==null;poll++){SystemClock.sleep(100);for(int n=0;n<((LeoActivity)a).root.getChildCount();n++)if(((LeoActivity)a).root.getChildAt(n) instanceof ListView)tones=(ListView)((LeoActivity)a).root.getChildAt(n);}check(tones!=null&&tones.getCount()>1,"tone library "+type);Uri current=RingtoneManager.getActualDefaultRingtoneUri(c,type);RingtoneManager.setActualDefaultRingtoneUri(c,type,current);check(Objects.equals(current,RingtoneManager.getActualDefaultRingtoneUri(c,type)),"tone write/read roundtrip");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);}capture("sound");close(a);a=null;passed.add("three real tone libraries and same-value write/read");
        a=open(StorageSettingsActivity.class);check(RecordingLocations.folders(c).containsKey("leo"),"internal recording location");for(File folder:RecordingLocations.folders(c).values()){if(!folder.isDirectory())folder.mkdirs();File probe=File.createTempFile(".leo-settings-test-",".tmp",folder);try(FileOutputStream output=new FileOutputStream(probe)){output.write(7);}check(probe.length()==1&&probe.delete(),"recording location writable");}capture("storage");close(a);a=null;passed.add("internal/available SD recording folders writable");
        a=open(BatterySettingsActivity.class);check(((LeoActivity)a).root!=null,"battery UI");capture("battery");close(a);a=null;a=open(NotificationSettingsActivity.class);capture("notifications");close(a);a=null;passed.add("battery and notification pages");
        result.putString("result","PASS "+passed);
    }catch(Throwable failure){result.putString("error",android.util.Log.getStackTraceString(failure));result.putString("passed",passed.toString());}finally{close(a);Settings.Secure.putString(c.getContentResolver(),InputSettingsActivity.MODE,mode);Settings.Secure.putString(c.getContentResolver(),InputSettingsActivity.DELAY,delay);Settings.System.putString(c.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS,brightness);Settings.System.putString(c.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS_MODE,automatic);Settings.System.putString(c.getContentResolver(),Settings.System.SCREEN_OFF_TIMEOUT,timeout);SharedPreferences.Editor restore=c.getSharedPreferences("settings-ui",0).edit().clear();for(Map.Entry<String,?> value:ui.entrySet())if(value.getValue() instanceof Integer)restore.putInt(value.getKey(),(Integer)value.getValue());restore.commit();}
        finish(result.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);
    }
}
